'use strict';
let HistoricPlayerData=null;
function historicDateLabel(date,precision){return precision>=11?date:precision===10?date.slice(0,7)+' · 월 단위':date.slice(0,4)+'년 · 연도 단위'}
function historicPlayerProfileHTML(p){
 const periods=(p.historyPeriods||[]).filter(r=>r.visibleFrom<=state.date),registrations=(p.tournamentEntries||[]).filter(r=>r.date<=state.date),games=(p.matchRecords||[]).filter(r=>r.date<=state.date),bench=(p.benchRecords||[]).filter(r=>r.date<=state.date),age=playerAge(p.birth,state.date);
 return `<article class="player-profile"><div class="player-profile-top"><div class="player-profile-identity"><span class="chip">고전 선수 · 출처별 역사 자료</span><h2>${esc(koreanPlayer(p))}</h2><p>${esc(p.name)} · ${esc(playerCountryName(p.country))}${age!==null?' · '+age+'세':''}</p></div><button data-watch-player="${esc(p.id)}" class="year-bookmark">${(state.playerWatch||[]).includes(p.id)?'★ 저장한 선수':'☆ 선수 저장'}</button></div><div class="player-evidence"><span>${state.date}까지 공개할 수 있는 역사 기록</span><b>${periods.length}개 소속 기간 · ${registrations.length}개 대회 등록 · ${games.length}개 확인 출전 · ${bench.length}개 벤치 등록</b><small>시작 연도만 알려진 소속은 그해 말부터 공개합니다. 연도·월 자료를 정확한 이적일로 바꾸지 않았습니다.</small></div><p class="note">생년 ${esc(p.birth||p.birthYear||'미확인')} · 국적은 참고 프로필입니다. 당시 대표팀은 대회별 기록에서 확인하세요. 개인의 전체 통산 출전 수나 최신 소속을 뜻하지 않습니다.</p><h3>확인된 소속 기간</h3><div class="transfer-career">${periods.slice().reverse().map(r=>`<article class="career-transfer"><div><strong>${teamLabel(r.clubKo||r.club,{date:r.visibleFrom})}</strong></div><small>${historicDateLabel(r.start,r.startPrecision)} 시작${r.endVisibleFrom&&r.endVisibleFrom<=state.date?' → '+historicDateLabel(r.end,r.endPrecision)+' 종료':' · 이 날짜까지 종료 정보 미공개'}</small></article>`).join('')||'<div class="empty">이 날짜까지 시작 시점을 확인한 소속 자료가 없습니다. 대회 등록 기록과 구분합니다.</div>'}</div>${registrations.length?`<h3>대표팀 대회 등록</h3><div class="table-wrap"><table><thead><tr><th>확인 기준일</th><th>대회</th><th>대표팀</th><th>등번호</th></tr></thead><tbody>${registrations.map(r=>`<tr><td>${r.date}</td><td>${esc(r.tournament)}</td><td>${esc(n(r.team))}</td><td>${r.number==='0'?'미수록':esc(r.number)}</td></tr>`).join('')}</tbody></table></div><p class="note">대회 명단은 해당 팀의 첫 경기일부터 공개합니다. 실제 명단 발표일이나 모든 경기의 선발 출전을 뜻하지 않습니다.</p>`:''}${games.length?`<h3>확인된 실제 출전</h3><div class="table-wrap"><table><thead><tr><th>경기일</th><th>소속팀·대표팀</th><th>출전 구분</th></tr></thead><tbody>${games.slice(-100).reverse().map(r=>`<tr><td><button class="text-button" data-goto="${r.date}">${r.date} ↗</button></td><td>${esc(n(r.team))}</td><td>${r.starter?'선발':'교체 출전'}</td></tr>`).join('')}</tbody></table></div><p class="note">개인 출전 시간이 없는 자료를 0분으로 채우지 않습니다.</p>`:''}${bench.length?'<details class="archive-lineups"><summary>벤치 등록 기록 '+bench.length+'개 · 실제 출전과 구분</summary>'+bench.slice(-100).reverse().map(r=>'<p>'+r.date+' · '+esc(n(r.team))+' · 벤치 명단</p>').join('')+'</details>':''}<p class="note">출처: Wikidata 소속 진술(CC0), Joshua C. Fjelstul의 World Cup Database(CC BY-SA 4.0), UEFA 공식 선발·벤치 자료. 프로필마다 실제 포함된 자료를 구분하며 모든 소속 경력이 완전하다고 보장하지 않습니다.</p><a class="source-link" href="${esc(p.source)}" target="_blank" rel="noopener">역사 자료 원문 · 이후 경력 포함 주의 ↗</a></article>`;
}
